// FEATURES.md and GLOSSARY.md, generated by pnpm verify from the registry and the glossary data.
import { AVOID, t, TERMS, VOICE } from '@idle-clash/content';
import type { Feature } from '@idle-clash/features';

const cell = (s: string) => s.replace(/\|/g, '\\|');

export function featuresMd(features: readonly Feature[]): string {
  const lines = [
    '# Features',
    '',
    'Generated by `pnpm verify` (step 2) from `packages/features/src/registry.ts`. Do not edit by hand.',
    '',
  ];
  if (!features.length) return `${lines.join('\n')}\nNo features yet.\n`;
  lines.push(
    '| Feature | Flag | Actions | Slots | Effects | Stop codes | Routes | Help |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
  );
  for (const f of features) {
    const flag = `${f.flag.on ? 'on' : 'off'}: ${f.flag.note}`;
    const actions = (f.content.actions ?? []).length;
    const routes = Object.keys(f.routes).join(', ') || 'none';
    const row = [
      f.id,
      flag,
      String(actions),
      Object.keys(f.slots).join(', '),
      f.effects.join(', '),
      f.stops.join(', ') || 'none',
      routes,
      t(f.help.title),
    ];
    lines.push(`| ${row.map(cell).join(' | ')} |`);
  }
  const bySlot = new Map<string, string[]>();
  for (const f of features) for (const s of Object.keys(f.slots)) bySlot.set(s, [...(bySlot.get(s) ?? []), f.id]);
  lines.push('', '## Slots filled', '', '| Slot | Filled by |', '| --- | --- |');
  for (const [slot, ids] of [...bySlot].sort()) lines.push(`| \`${slot}\` | ${ids.join(', ')} |`);
  return `${lines.join('\n')}\n`;
}

export function glossaryMd(): string {
  const lines = [
    '# Idle Clash: glossary',
    '',
    'Every player-facing term, with the one meaning it has everywhere. Generated by `pnpm verify` from `packages/content/src/glossary.ts`: add or change a term there. The content check fails when a string in `packages/content/src/strings/en.ts` uses a term to avoid.',
    '',
    '## Voice',
    '',
    VOICE,
    '',
    '## Terms',
    '',
    '| Term | Meaning |',
    '| --- | --- |',
    ...TERMS.map(([term, meaning]) => `| ${cell(term)} | ${cell(meaning)} |`),
    '',
    '## Terms to avoid',
    '',
    '| Avoid | Use | Allowed in |',
    '| --- | --- | --- |',
    ...AVOID.map((a) => `| ${a.words.join(', ')} | ${a.use} | ${a.except?.join(', ') ?? ''} |`),
  ];
  return `${lines.join('\n')}\n`;
}
